def validate_batch(records, schema) -> tuple[list, list]:
    valid = []
    errors = []

    for record in records:
        record_errors = []
        for field, expected_type in schema.items():
            if field not in record:
                record_errors.append({
                    "record": record, "field": field, "error": "missing"
                })
            elif not isinstance(record[field], expected_type):
                record_errors.append({
                    "record": record, "field": field,
                    "error": f"expected {expected_type}, got {type(record[field])}"
                })
        if record_errors:
            errors.extend(record_errors)
        else:
            valid.append(record)

    return valid, errors

