from datetime import datetime, timedelta
from airflow.decorators import dag, task

DEFAULT_ARGS = {
    "owner": "data-engineering",
    "depends_on_past": False,
    "retries": 2,
    "retry_delay": timedelta(minutes=5),
    "email_on_failure": True,
    "email": ["team@company.com"],
}

@dag(
    dag_id="daily_etl_pipeline",
    default_args=DEFAULT_ARGS,
    schedule="0 6 * * *",
    start_date=datetime(2025, 1, 1),
    catchup=False,
    max_active_runs=1,
    tags=["etl", "daily", "production"],
)
def daily_pipeline():

    @task()
    def extract(ds: str = None) -> dict:
        """Extract: return metadata about source."""
        return {"source": f"s3://raw/data/{ds}/", "date": ds}

    @task()
    def transform(extract_info: dict) -> dict:
        """Transform: return metadata about output."""
        return {
            "output": f"s3://processed/{extract_info['date']}/",
            "records": 1000,
        }

    @task()
    def load(transform_info: dict) -> dict:
        """Load: return status."""
        return {"status": "success", "records_loaded": transform_info["records"]}

    # Wiring
    extracted = extract()
    transformed = transform(extracted)
    load(transformed)

daily_pipeline()

# ============================================================

from airflow.providers.amazon.aws.hooks.s3 import S3Hook
from airflow.providers.postgres.hooks.postgres import PostgresHook
import subprocess
import json
import os

@dag(
    dag_id="claims_pipeline_v2",
    default_args=DEFAULT_ARGS,
    schedule="0 6 * * *",
    start_date=datetime(2025, 1, 1),
    catchup=False,
    max_active_runs=1,
    tags=["claims", "production"],
)
def claims_pipeline_v2():

    @task()
    def validate_source(ds: str = None) -> dict:
        """Check source file exists and has valid size."""
        hook = S3Hook(aws_conn_id="aws_default")
        key = f"claims/daily/{ds}/claims.json"

        # head_object returns metadata (size, content-type, etc)
        metadata = hook.head_object(key=key, bucket_name="raw-data")
        size_mb = metadata["ContentLength"] / (1024 * 1024)

        if size_mb < 0.001:
            raise ValueError(f"File too small: {size_mb:.4f} MB")
        if size_mb > 5000:
            raise ValueError(f"File too large: {size_mb:.1f} MB")

        return {
            "source_path": f"s3://raw-data/{key}",
            "size_mb": round(size_mb, 2),
            "date": ds,
        }

    @task()
    def process_data(source_info: dict) -> dict:
        """Run Spark job via subprocess. Return metadata."""
        cmd = [
            "spark-submit",
            "--master", "yarn",
            "--deploy-mode", "client",
            "/opt/airflow/scripts/process_claims.py",
            "--source", source_info["source_path"],
            "--date", source_info["date"],
        ]

        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=7200,
        )

        if proc.returncode != 0:
            raise RuntimeError(
                f"Spark failed (exit {proc.returncode}): {proc.stderr[-2000:]}"
            )

        # Parse JSON metadata from last line of stdout
        for line in reversed(proc.stdout.strip().split("\n")):
            try:
                return json.loads(line)
            except json.JSONDecodeError:
                continue

        return {"status": "success", "output": proc.stdout[-500:]}

    @task()
    def quality_check(process_info: dict) -> dict:
        """Validate output: check row count in database."""
        hook = PostgresHook(postgres_conn_id="postgres_prod")
        result = hook.get_first("SELECT COUNT(*) FROM claims_silver")
        row_count = result[0] if result else 0

        if row_count == 0:
            raise ValueError("ZERO rows in claims_silver after processing!")

        return {"status": "passed", "row_count": row_count}

    # Wiring
    source = validate_source()
    processed = process_data(source)
    quality_check(processed)

claims_pipeline_v2()

